<!-- Teacher desktop: overview → evidence → action. Pinned light/emerald layout;
     only the overview has metric cards. Synthetic data is an explicit mode. -->
<template>
  <TeachingPortal v-if="route.query.demo!=='1'"/><AppLayout v-else>
    <div class="tw" :class="{ 'overview-refined': surface === 'dashboard', 'data-refreshing': refreshing }">
      <RouterLink v-if="safeTeacherReturn(q.returnTo)" :to="q.returnTo" class="back">{{ q.returnTo.startsWith('/teacher/analytics') ? '返回数据分析' : '返回来源页面' }}</RouterLink><p v-if="q.analyticsFrom" class="scope-note">分析来源范围：{{q.from}} ～ {{q.to}}</p><RouterLink v-if="!safeTeacherReturn(q.returnTo) &amp;&amp; q.returnClass" :to="{ path: `/teacher/classes/${q.returnClass}`, query: { demo: q.demo, semester: q.semester } }" class="back">← 返回班级分析</RouterLink>
      <RouterLink v-else-if="!safeTeacherReturn(q.returnTo) &amp;&amp; surface !== 'dashboard'" :to="link('/teacher/dashboard')" class="back">← 教学总览</RouterLink>
      <header class="page-head">
        <div><h1>{{ titles[surface] }}</h1><p>{{ descriptions[surface] }}</p></div>
        <div class="global-filters">
          <label>学期<select :disabled="q.demo !== '1'" :value="q.semester || '2026-1'" @change="set('semester', $event.target.value)"><option value="2026-1">2026–2027 第一学期</option><option value="2025-2">2025–2026 第二学期</option></select></label>
          <label>班级<select :disabled="q.demo !== '1'" :value="q.class || ''" @change="set('class', $event.target.value)"><option value="">全部班级</option><option v-for="item in classes" :key="item">{{ item }}</option></select></label>
          <label v-if="surface === 'training-records'">学生<select :disabled="q.demo !== '1'" :value="q.student || ''" @change="set('student', $event.target.value)"><option value="">全部学生</option><option v-for="s in data?.students || []" :key="s.id" :value="s.id">{{ s.name }}</option></select></label>
          <label v-if="surface !== 'reviews'">岗位<select aria-label="岗位" :disabled="q.demo !== '1'" :value="q.position || ''" @change="set('position', $event.target.value)"><option value="">全部岗位</option><option v-for="item in positions" :key="item">{{ item }}</option></select></label>
          <label>时间<select :disabled="q.demo !== '1'" :value="q.period || '30d'" @change="set('period', $event.target.value)"><option value="30d">近30天</option><option value="7d">近7天</option><option value="90d">近90天</option><option value="semester">本学期</option></select></label>
          <RouterLink v-if="surface === 'dashboard'" class="primary" :to="link('/teacher/tasks/create')">发布训练任务</RouterLink>
        </div>
      </header>
      <div class="data-notice" role="status">
        <strong v-if="surface === 'dashboard'" class="mode-label">{{ q.demo === '1' ? '演示模式' : '真实数据模式' }}</strong>
        <span v-if="q.demo === '1'">{{ surface === 'dashboard' ? '' : '演示模式 · ' }}示例周期截至{{data?.referenceDate}}，数据与操作不写入真实系统。</span>
        <span v-else>{{ surface === 'dashboard' ? '' : '真实数据模式 · ' }}当前接口为全周期统计；周期、班级、成长与待办数据尚未开放。</span>
        <button type="button" @click="switchMode">{{ q.demo === '1' ? '切换真实数据' : '查看演示效果' }}</button>
      </div>
      <div v-if="actionSuccess" class="action-success" role="status">{{ actionSuccess }}<button @click="actionSuccess = ''" aria-label="关闭操作提示">关闭</button></div>
      <div v-if="loading" class="state" role="status">正在加载教师数据…</div>
      <div v-else-if="error" class="state error" role="alert"><p>{{ error }}</p><button @click="load">重新加载</button><button @click="switchMode">查看演示效果</button></div>
      <template v-else-if="data?.source === 'live'">
        <template v-if="surface === 'dashboard'">
          <section class="metrics"><RouterLink v-for="m in liveMetrics" :key="m.title" :to="link(m.path)" class="metric"><h2>{{ m.title }}</h2><strong>{{ m.value }}</strong><p>{{ m.note }}</p><span>{{ m.action }} →</span></RouterLink></section>
          <section class="panel"><h2>近7天新建面试趋势</h2><p class="muted">当前接口统计新建会话，尚不能作为有效训练记录或活跃学生趋势。</p><TeacherChart :points="data.overview.trainingTrend || []" :series="[{ key: 'count', name: '新建面试会话' }]" label="近7天新建面试会话数量" /></section>
          <section class="panel"><h2>学生训练情况 · 全周期</h2><p class="muted">当前接口不含班级与学生标识，暂不提供学生详情下钻；训练次数包含全部面试会话。</p><div class="table-scroll"><table><thead><tr><th>学生</th><th>最近训练岗位</th><th>面试会话数</th><th>最近训练</th><th>训练状态</th></tr></thead><tbody><tr v-for="(s, i) in data.overview.studentTrainingList || []" :key="i"><td>{{ s.studentName }}</td><td>{{ s.position }}</td><td>{{ s.trainingCount }}</td><td>{{ s.lastTrainingTime || '—' }}</td><td>{{ s.status }}</td></tr></tbody></table></div><p v-if="!data.overview.studentTrainingList?.length" class="state">暂无学生训练数据</p></section>
        </template>
        <section v-else class="panel state"><h2>{{ titles[surface] }}暂未接入数据</h2><p>当前教师接口缺少{{ missing[surface] }}。可查看演示效果了解筛选、下钻与处理流程。</p><button class="primary" @click="switchMode">查看演示效果</button></section>
      </template>
      <template v-else-if="data">
        <template v-if="surface === 'dashboard'">
          <section class="metrics"><RouterLink v-for="m in metrics" :key="m.title" :to="link(m.path, m.query)" class="metric"><h2>{{ m.title }}</h2><strong :class="{ orange: m.title === '待点评报告' }">{{ m.value }}<small>{{ m.unit }}</small></strong><p>{{ m.note }}</p><span>{{ m.action }} →</span></RouterLink></section>
          <div class="overview-top">
            <section class="panel"><div class="panel-head"><h2>训练情况</h2></div><TeacherChart :points="trend" :series="[{key:'count',name:'完成训练次数'},{key:'active',name:'活跃学生数'}]" label="训练参与趋势" @select="showDate" /><p class="data-insight">当前范围内，<strong>{{ trainedCount }}名学生</strong>参与训练，产生<strong>{{ filtered.records.length }}条有效记录</strong>；参与率{{ participation }}%。</p></section>
            <section class="panel"><div class="panel-head"><h2>班级能力表现</h2><RouterLink :to="link('/teacher/analytics/abilities')">查看能力分析 →</RouterLink></div><div v-if="!q.position" class="state guided-state"><strong>查看同岗位能力差距</strong><p>选择岗位后展示班级各项能力与目标值的差距。</p><button type="button" @click="focusPosition">选择岗位</button></div><div v-else-if="!abilityValues.length" class="state guided-state"><strong>当前范围暂无完整能力评分</strong><p>可调整班级或时间范围，查看已有评分记录。</p><button @click="resetOverviewFilters">重置筛选</button></div><RouterLink v-for="a in abilityValues" :key="a.name" :to="link('/teacher/analytics/abilities', { ability: a.name })" class="ability-row"><span>{{ a.name }}</span><div class="bar-track"><i :style="{ width: `${a.value}%` }"></i><b class="target" style="left:80%"></b></div><span>{{ a.value }} / 80</span><span class="orange">{{ a.value - 80 }}</span></RouterLink></section>
          </div>
          <div class="overview-bottom">
            <section class="panel task-panel"><div class="module-heading"><div class="panel-head"><h2>进行中的训练任务</h2><RouterLink :to="link('/teacher/tasks')">查看全部 →</RouterLink></div><p class="muted">按截止时间展示最近5项。</p></div><div v-for="t in activeTasks" :key="t.id" class="task-row"><RouterLink :to="link(`/teacher/tasks/${t.id}`)">{{ t.name }}<small>{{data.classes.find(c=>c.id===t.classId)?.name}}</small></RouterLink><div class="stack"><i v-for="(key, i) in ['completed', 'ongoing', 'notStarted', 'overdue']" :key="key" :style="{ width: `${t[key] / taskTotal(t) * 100}%`, background: stackColors[i] }"></i></div><span>{{ t.completed }}/{{ taskTotal(t) }}</span><small class="deadline" :class="{ orange: deadlineDays(t) < 0 }">{{ t.deadline.slice(5,10) }}<span>{{ deadlineText(t) }}</span></small></div><div v-if="!activeTasks.length" class="state guided-state"><strong>当前范围没有进行中的任务</strong><p>可调整筛选，或为所带学生发布训练任务。</p><RouterLink class="primary" :to="link('/teacher/tasks/create')">发布训练任务</RouterLink></div><div class="legend"><span v-for="(label, i) in ['已完成', '进行中', '未开始', '逾期']" :key="label"><i :style="{ background: stackColors[i] }"></i>{{ label }}</span></div></section>
            <section class="panel"><h2>需要关注的学生</h2><RouterLink v-for="s in attention" :key="s.id" :to="link('/teacher/growth', { student: s.id })" class="attention"><strong>{{ s.name }}</strong><small>{{ s.className }}</small><p>{{ s.growth.status === '持续下降' ? `最近3次累计下降${s.growth.loss}分` : s.count ? `${daysAgo(s.last)}天未训练` : '当前周期未训练' }}</p></RouterLink><div v-if="!attention.length" class="state guided-state"><strong>当前没有重点关注学生</strong><p>当前范围内未发现符合关注条件的学生。</p></div></section>
            <section class="panel todo-panel"><div class="module-heading"><h2>今日待办</h2></div><div v-if="todos.every(todo => todo.count === 0)" class="todo-clear"><strong>当前没有待处理事项</strong><p>点评、任务逾期和连续下降学生均已查看完毕或暂无记录。</p></div><RouterLink v-for="todo in todos" :key="todo.tab" :to="link('/teacher/reviews', { tab: todo.tab })" class="todo"><strong class="orange">{{ todo.count }}</strong><span>{{ todo.label }}<small>{{ todo.action }} →</small></span></RouterLink></section>
          </div>
        </template>

        <template v-else-if="surface === 'activity'">
          <div class="two-charts"><section class="panel"><div class="panel-head"><h2>活跃状态分布</h2><small>共{{ filtered.students.length }}人 · 参与率{{ participation }}%</small></div><p class="muted">当前周期阈值：高活跃≥{{ q.period === '7d' ? 3 : 5 }}次，正常训练{{ q.period === '7d' ? '2' : '3–4' }}次</p><button v-for="(status, i) in activityStatuses" :key="status" class="distribution-row" :class="{ selected: q.activity === status }" @click="toggle('activity', status)"><span>{{ status }}</span><div class="bar-track"><i :style="{ width: `${percent(activityCount(status))}%`, background: activityColors[i] }"></i></div><b>{{ activityCount(status) }}人</b><small>{{ percent(activityCount(status)).toFixed(1) }}%</small></button></section><section class="panel"><h2>训练参与趋势</h2><p class="muted">每天有有效训练记录的学生人数</p><TeacherChart :points="trend" :series="[{ key: 'active', name: '训练学生数' }]" label="训练参与趋势" @select="showDate" /></section></div>
          <section class="panel"><div class="panel-head"><h2>学生明细 <small>共{{ studentRows.length }}名学生</small></h2><div class="inline"><span>已选择{{ selected.length }}名</span><RouterLink v-if="selected.length" class="primary" :to="link('/teacher/tasks/create', { students: selected.join(',') })">发布训练任务</RouterLink><button v-else disabled>发布训练任务</button></div></div>
            <div class="table-filters"><label>活跃状态<select :disabled="q.demo !== '1'" :value="q.activity || ''" @change="set('activity', $event.target.value)"><option value="">全部</option><option v-for="s in activityStatuses" :key="s">{{ s }}</option></select></label><label>最近训练<select :disabled="q.demo !== '1'" :value="q.last || ''" @change="set('last', $event.target.value)"><option value="">不限</option><option value="today">今天</option><option value="3">3天内</option><option value="7">7天内</option><option value="older">7天以上</option><option value="never">当前周期未训练</option></select></label><label>排序<select :disabled="q.demo !== '1'" :value="q.sort || 'attention'" @change="set('sort', $event.target.value)"><option value="attention">需要关注优先</option><option value="most">训练最多</option><option value="least">训练最少</option><option value="recent">最近训练</option><option value="oldest">最久未训练</option></select></label><input aria-label="搜索姓名或学号" placeholder="搜索姓名或学号" :value="q.search || ''" @input="set('search', $event.target.value)" /></div>
            <div class="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="选择本页所有学生" :checked="allSelected" @change="selectPage($event.target.checked)" /></th><th>姓名</th><th>班级</th><th>目标岗位</th><th>近周期训练次数</th><th>最近训练</th><th>连续活跃</th><th>活跃状态</th><th>操作</th></tr></thead><tbody><tr v-for="s in pagedStudents" :key="s.id"><td><input v-model="selected" type="checkbox" :value="s.id" :aria-label="`选择${s.name}`" /></td><td><RouterLink :to="link(`/teacher/students/${s.id}`)">{{ s.name }}</RouterLink></td><td>{{ s.className }}</td><td>{{ s.position }}</td><td><RouterLink :to="link('/teacher/training-records', { student: s.id })">{{ s.count }}次</RouterLink></td><td>{{ date(s.last) }}</td><td>{{ s.streak }}天</td><td><span class="badge" :class="tone(s.activity)">{{ s.activity }}</span></td><td><button class="text" @click="showStudent(s.id)">查看详情</button></td></tr></tbody></table></div><p v-if="!studentRows.length" class="state">没有符合条件的学生 <button @click="clearLocal">清除明细筛选</button></p><div class="pagination"><span>共{{ studentRows.length }}条</span><button :disabled="page === 1" @click="set('page', page - 1)">上一页</button><span>{{ page }}/{{ totalPages }}</span><button :disabled="page >= totalPages" @click="set('page', page + 1)">下一页</button></div>
          </section>
        </template>

        <template v-else-if="surface === 'training-records'">
          <section class="panel"><div class="panel-head"><h2>学生训练频次分布</h2><small>{{ filtered.records.length }}条有效训练记录 · {{ trainedCount }}名学生参与</small></div><button v-for="(bucket, i) in frequencyBuckets" :key="bucket.key" class="distribution-row wide" :class="{ selected: q.frequency === bucket.key }" @click="filterFrequency(bucket.key)"><span>{{ bucket.label }}</span><div class="bar-track"><i :style="{ width: `${percent(frequencyCount(bucket.key))}%`, background: activityColors[Math.min(i, 3)] }"></i></div><b>{{ frequencyCount(bucket.key) }}人</b><small>{{ percent(frequencyCount(bucket.key)).toFixed(1) }}%</small></button></section>
          <section class="panel"><div class="panel-head"><h2>训练记录 <small>共{{ recordRows.length }}条</small></h2><button v-if="q.comparable" class="text" @click="set('comparable', '')">清除可比较训练筛选 ×</button></div><div class="table-filters"><label>训练形式<select :disabled="q.demo !== '1'" :value="q.type || ''" @change="set('type', $event.target.value)"><option value="">全部</option><option>AI虚拟面试</option><option>专项训练</option></select></label><label>训练来源<select :disabled="q.demo !== '1'" :value="q.source || ''" @change="set('source', $event.target.value)"><option value="">全部</option><option>学生自主</option><option>教师任务</option></select></label><label>训练内容<select :disabled="q.demo !== '1'" :value="q.content || ''" @change="set('content', $event.target.value)"><option value="">全部</option><option v-for="item in [...new Set(filtered.records.map(r => r.content))]" :key="item">{{ item }}</option></select></label><label>完成时间<input type="date" :value="q.date || ''" @change="set('date', $event.target.value)" /></label><input aria-label="搜索学生、学号或训练内容" placeholder="搜索学生、学号或训练内容" :value="q.search || ''" @input="set('search', $event.target.value)" /></div><div class="table-scroll"><table><thead><tr><th>学生</th><th>班级</th><th>训练岗位</th><th>训练形式</th><th>训练内容</th><th>训练来源</th><th><button class="text" @click="set('sort', q.sort === 'oldest' ? '' : 'oldest')">完成时间 {{ q.sort === 'oldest' ? '↑' : '↓' }}</button></th><th>用时</th><th>结果</th><th>操作</th></tr></thead><tbody><tr v-for="r in pagedRecords" :key="r.id"><td><RouterLink :to="link(`/teacher/students/${r.studentId}`)">{{ student(r.studentId)?.name }}</RouterLink></td><td>{{ student(r.studentId)?.className }}</td><td>{{ r.position }}</td><td><span class="badge">{{ r.type }}</span></td><td>{{ r.content }}</td><td><RouterLink v-if="r.taskId" :to="link(`/teacher/tasks/${r.taskId}`)">{{ r.source }}</RouterLink><span v-else>{{ r.source }}</span></td><td>{{ date(r.completedAt) }}</td><td>{{ r.duration }}</td><td><span class="badge" :class="tone(r.result)">{{ r.result }}</span></td><td><RouterLink v-if="r.type === 'AI虚拟面试'" :to="link(`/teacher/reports/${r.reportId||r.id}`)">查看报告</RouterLink><button v-else class="text" @click="drawer = { type: 'record', item: r }">查看记录</button></td></tr></tbody></table></div><p v-if="!recordRows.length" class="state">没有符合条件的训练记录 <button @click="clearLocal">清除明细筛选</button></p><div class="pagination"><span>共{{ recordRows.length }}条</span><button :disabled="page === 1" @click="set('page', page - 1)">上一页</button><span>{{ page }}/{{ totalPages }}</span><button :disabled="page >= totalPages" @click="set('page', page + 1)">下一页</button></div></section>
        </template>

        <template v-else-if="surface === 'growth'">
          <div class="two-charts"><section class="panel"><div class="panel-head"><h2>成长状态分布</h2><button class="text" @click="drawer = { type: 'rules' }">成长判定规则</button></div><p class="muted">共{{ filtered.students.length }}名学生 · {{ comparableStudents.length }}名可比较</p><button v-for="(status, i) in growthStatuses" :key="status" class="distribution-row" :class="{ selected: q.growth === status }" @click="toggle('growth', status)"><span>{{ status }}</span><div class="bar-track"><i :style="{ width: `${percent(growthCount(status))}%`, background: growthColors[i] }"></i></div><b>{{ growthCount(status) }}人</b><small>{{ percent(growthCount(status)).toFixed(1) }}%</small></button></section><section class="panel"><h2>成长变化分布</h2><p class="muted">仅含{{ comparableStudents.length }}名可比较学生 · 以0为界</p><div class="growth-histogram"><button v-for="(bucket, i) in deltaBuckets" :key="bucket.key" :class="{ chosen: q.delta === bucket.key }" @click="toggle('delta', bucket.key)"><strong>{{ deltaCount(bucket.key) }}</strong><i :style="{ height: `${deltaCount(bucket.key) / Math.max(1, ...deltaBuckets.map(b => deltaCount(b.key))) * 135}px`, background: ['#ef6b5a','#ff9a3d','#d1d5db','#a7f3d0','#6ee7b7','#10b981'][i] }"></i><small>{{ bucket.label }}</small></button></div><p class="histogram-caption"><span class="orange">← 下降</span><span>提升 →</span></p></section></div>
          <section class="panel"><div class="panel-head"><h2>学生成长明细 <small>共{{ studentRows.length }}名</small></h2><RouterLink v-if="selected.length" class="primary" :to="link('/teacher/tasks/create', { students: selected.join(',') })">发布针对性训练（{{ selected.length }}人）</RouterLink></div><div class="table-filters"><label>成长状态<select :disabled="q.demo !== '1'" :value="q.growth || ''" @change="set('growth', $event.target.value)"><option value="">全部</option><option v-for="s in growthStatuses" :key="s">{{ s }}</option></select></label><label>主要变化维度<select :disabled="q.demo !== '1'" :value="q.ability || ''" @change="set('ability', $event.target.value)"><option value="">全部</option><option v-for="a in abilities" :key="a">{{ a }}</option></select></label><label>排序<select :disabled="q.demo !== '1'" :value="q.sort || 'attention'" @change="set('sort', $event.target.value)"><option value="attention">需要关注优先</option><option value="deltaDesc">变化值从高到低</option><option value="deltaAsc">变化值从低到高</option></select></label><input aria-label="搜索姓名或学号" placeholder="搜索姓名或学号" :value="q.search || ''" @input="set('search', $event.target.value)" /></div><div class="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="选择本页所有学生" :checked="allSelected" @change="selectPage($event.target.checked)" /></th><th>学生</th><th>班级</th><th>训练岗位</th><th>可比较训练</th><th>前期表现</th><th>近期表现</th><th>变化Δ</th><th>主要变化</th><th>成长状态</th><th>操作</th></tr></thead><tbody><tr v-for="s in pagedStudents" :key="s.id"><td><input v-model="selected" type="checkbox" :value="s.id" :aria-label="`选择${s.name}`" /></td><td><RouterLink :to="link(`/teacher/students/${s.id}`)">{{ s.name }}</RouterLink></td><td>{{ s.className }}</td><td>{{ s.position }}</td><td><RouterLink :to="link('/teacher/training-records', { student: s.id, comparable: 'true' })">{{ s.growth.count }}次</RouterLink></td><td>{{ decimal(s.growth.early) }}</td><td>{{ decimal(s.growth.current) }}</td><td :class="s.growth.delta < 0 ? 'orange' : 'green'">{{ signed(s.growth.delta) }}</td><td><button class="text" @click="drawer = { type: 'growth', item: s }">{{ s.growth.changes?.[0] ? `${s.growth.changes[0].name} ${signed(s.growth.changes[0].delta)}` : '可比较训练不足6次' }}</button></td><td><span class="badge" :class="tone(s.growth.status)">{{ s.growth.status }}</span></td><td><button class="text" @click="drawer = { type: 'growth', item: s }">查看详情</button></td></tr></tbody></table></div><p v-if="!studentRows.length" class="state">没有符合条件的学生 <button @click="clearLocal">清除明细筛选</button></p><div class="pagination"><span>共{{ studentRows.length }}条</span><button :disabled="page === 1" @click="set('page', page - 1)">上一页</button><span>{{ page }}/{{ totalPages }}</span><button :disabled="page >= totalPages" @click="set('page', page + 1)">下一页</button></div></section>
        </template>

        <template v-else-if="surface === 'reviews'">
          <div class="todo-tabs" role="tablist" aria-label="待办类型"><button v-for="todo in todos" :key="todo.tab" role="tab" :aria-selected="tab === todo.tab" :class="{ chosen: tab === todo.tab }" @click="set('tab', todo.tab)">{{ todo.label }} <b>{{ todo.count }}</b></button></div>
