ge >= totalPages" @click="set('page', page + 1)">下一页</button></div>
          </section><section class="panel review-detail" v-if="currentReview"><h2>{{ student(currentReview.studentId)?.name }}</h2><p class="muted">{{ student(currentReview.studentId)?.className }} · {{ student(currentReview.studentId)?.position }}</p><template v-if="tab === 'pending'"><h3>本次训练信息</h3><dl><dt>训练内容</dt><dd>{{ currentReview.content }}</dd><dt>训练形式</dt><dd>{{ currentReview.type }}</dd><dt>提交时间</dt><dd>{{ date(currentReview.completedAt) }}</dd><dt>用时</dt><dd>{{ currentReview.duration }}</dd></dl><h3>报告摘要</h3><p class="hint">{{ pendingFinding(currentReview) }}；请结合原始报告核查。</p><div class="inline"><RouterLink class="primary" :to="link(`/teacher/reports/${currentReview.id}`, { mode: 'review' })">开始点评</RouterLink></div></template><template v-else-if="tab === 'overdue'"><h3>逾期任务上下文</h3><dl><dt>任务</dt><dd>{{ task(currentReview.taskId)?.name }}</dd><dt>截止时间</dt><dd>{{ currentReview.deadline }}</dd><dt>逾期</dt><dd>{{ currentReview.days }}天</dd><dt>近期训练</dt><dd>{{ student(currentReview.studentId)?.count }}次</dd><dt>最近训练</dt><dd>{{ date(student(currentReview.studentId)?.last) }}</dd><dt>活跃状态</dt><dd>{{ student(currentReview.studentId)?.activity }}</dd></dl><RouterLink :to="link(`/teacher/tasks/${currentReview.taskId}`)">查看任务</RouterLink><p class="muted">同一任务的学生可在左侧选择后批量延期。</p></template><template v-else><h3>最近3次表现</h3><p>{{ currentReview.growth.records.slice(-3).map(r => r.score).join(' → ') }}</p><p class="orange">累计下降{{ currentReview.growth.loss }}分</p><h3>主要能力变化</h3><p v-for="a in currentReview.growth.changes" :key="a.name">{{ a.name }} {{ signed(a.delta) }}</p><p>最近训练：{{ date(currentReview.last) }}</p><p>活跃状态：{{ currentReview.activity }}</p><div class="drawer-actions"><RouterLink :to="link('/teacher/growth', { student: currentReview.studentId })">成长情况</RouterLink><RouterLink :to="link('/teacher/training-records', { student: currentReview.studentId })">训练记录</RouterLink><RouterLink class="primary" :to="link('/teacher/tasks/create', { students: currentReview.studentId })">发布针对性训练</RouterLink></div></template></section><section v-else class="panel state">当前没有待处理事项</section></div>
        </template>
      </template>
      <TeacherDrawer modal class="workspace-detail-window" :open="!!drawer" :title="drawerTitle" @close="drawer = null">
        <template v-if="drawer?.type === 'rules'"><section class="workspace-rule"><h3>可比较范围</h3><p>只比较同一学生、同一岗位能力模型、同一评分模型版本下的有效完整评分记录。切换岗位或模型后开启新的阶段。</p></section><section class="workspace-rule"><h3>变化计算</h3><p>至少6次可比较训练：前3次平均与最近3次平均之差为Δ。有效提升：Δ≥3；基本稳定：−3&lt;Δ&lt;3；轻微下降：Δ≤−3。</p></section><section class="workspace-rule"><h3>持续下降判定</h3><p>最近3次表现依次下降且累计下降≥5时，优先判为持续下降。数据不足时不生成变化值。</p></section><section class="workspace-rule"><h3>区间边界</h3><p>区间边界：Δ≤−6、−6&lt;Δ≤−3、−3&lt;Δ&lt;0、0≤Δ&lt;3、3≤Δ&lt;6、Δ≥6。</p></section></template>
        <template v-else-if="drawer?.type === 'growth'"><h3>{{ drawer.item.name }} · {{ drawer.item.position }}</h3><p>{{ drawer.item.growth.status }} · {{ drawer.item.growth.count }}次可比较训练</p><TeacherChart :points="drawer.item.growth.records.slice(-6).map(r => ({ date: r.completedAt.slice(0,10), score: r.score }))" :series="[{ key: 'score', name: '同岗位表现指数' }]" label="最近6次成长趋势" /><p v-for="a in drawer.item.growth.changes" :key="a.name">{{ a.name }} {{ signed(a.delta) }}</p><div class="drawer-actions"><RouterLink :to="link(`/teacher/students/${drawer.item.id}`)">学生详情</RouterLink><RouterLink :to="link('/teacher/training-records', { student: drawer.item.id, comparable: 'true' })">可比较训练</RouterLink><RouterLink :to="link('/teacher/tasks/create', { students: drawer.item.id })">发布针对性训练</RouterLink></div></template>
        <template v-else-if="drawer?.type === 'record'"><dl><dt>学生</dt><dd>{{ student(drawer.item.studentId)?.name }}</dd><dt>训练内容</dt><dd>{{ drawer.item.content }}</dd><dt>发生时岗位</dt><dd>{{ drawer.item.position }}</dd><dt>完成时间</dt><dd>{{ date(drawer.item.completedAt) }}</dd><dt>用时</dt><dd>{{ drawer.item.duration }}</dd><dt>结果</dt><dd>{{ drawer.item.result }}</dd></dl><p>专项训练记录未生成完整面试报告。</p><RouterLink v-if="drawer.item.taskId" :to="link(`/teacher/tasks/${drawer.item.taskId}`)">查看来源任务</RouterLink></template>
        <template v-else-if="drawer?.type === 'student'"><dl><dt>姓名</dt><dd>{{ drawer.item.name }}</dd><dt>学号</dt><dd>{{ drawer.item.number }}</dd><dt>班级</dt><dd>{{ drawer.item.className }}</dd><dt>目标岗位</dt><dd>{{ drawer.item.position }}</dd><dt>近周期训练</dt><dd>{{ drawer.item.count }}次</dd><dt>活跃状态</dt><dd>{{ drawer.item.activity }}</dd></dl><div class="drawer-actions"><RouterLink :to="link(`/teacher/students/${drawer.item.id}`)">学生详情</RouterLink><RouterLink :to="link('/teacher/training-records', { student: drawer.item.id })">训练记录</RouterLink></div></template>
        <template v-else-if="drawer?.type === 'date'"><p>{{ drawer.item.date }}：完成{{ drawer.item.count }}次有效训练，{{ drawer.item.active }}名学生参与。</p><RouterLink :to="link('/teacher/training-records', { date: drawer.item.date })">查看当天训练记录</RouterLink></template>
        <form class="workspace-extend-form" v-else-if="drawer?.type === 'extend'" @submit.prevent="extend"><p>演示操作：修改该任务截止时间，适用于任务全部参与学生。</p><label>新截止日期<input v-model="newDeadline" type="date" :min="data.referenceDate" required /></label><footer class="workspace-dialog-actions"><button type="button" @click="drawer=null">取消</button><button type="submit" class="primary">保存演示延期</button></footer><p v-if="actionError" role="alert">{{ actionError }}</p></form>
      </TeacherDrawer>
    </div>
  </AppLayout>
</template>

<script setup>
import TeachingPortal from '../TeachingPortal.vue'
import {normalizeTeacherQuery,teacherContext,safeTeacherReturn} from '../../services/teacherContext.js'
import { ref, computed, watch, nextTick, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppLayout from '../../components/layout/AppLayout.vue'
import TeacherChart from '../../components/teacher/TeacherChart.vue'
import TeacherDrawer from '../../components/teacher/TeacherDrawer.vue'
import { loadTeacherWorkspace, getDemoWorkspace } from '../../services/teacherWorkspace'
import {loadTasks,extendDeadline,lifecycle} from '../../services/trainingTasks.js'
import {currentAbility} from '../../services/teacherContext.js'
import { abilities, classes, positions, filterData, dailyTrend, daysAgo, timestamp } from '../../services/teacherModel'
const refreshing = ref(false), actionSuccess = ref('')
let refreshTimer
onUnmounted(() => clearTimeout(refreshTimer))
const props = defineProps({ surface: String })
const route = useRoute(), router = useRouter(), q = computed(() => normalizeTeacherQuery(route.query))
const surface = computed(() => props.surface || route.meta.teacherSurface || 'dashboard')
const data = ref(null), loading = ref(true), error = ref(''), drawer = ref(null), selected = ref([]), newDeadline = ref(''), actionError = ref('')
const titles = { dashboard: '教学总览', activity: '学生活跃情况', 'training-records': '训练明细', growth: '学生成长情况', reviews: '教师待办中心' }
const descriptions = { dashboard: '查看所带班级近期训练情况与学生表现', activity: '查看学生在当前周期内的训练参与情况', 'training-records': '查看当前范围内的有效训练记录', growth: '比较同一学生同岗位前后训练表现', reviews: '集中处理待点评报告、任务逾期与连续下降学生' }
const missing = { activity: '班级、有效训练记录和周期活跃统计', 'training-records': '有效训练记录、报告标识和任务来源', growth: '可比较评分记录、岗位模型和评分版本', reviews: '报告点评、任务截止时间与连续下降记录' }
const activityStatuses = ['高活跃', '正常训练', '低活跃', '未训练'], activityColors = ['#10b981', '#6ee7b7', '#ff9a3d', '#b3b8c3']
const growthStatuses = ['有效提升', '基本稳定', '轻微下降', '持续下降', '数据不足'], growthColors = ['#10b981', '#6ee7b7', '#ff9a3d', '#ef6b5a', '#b3b8c3']
const stackColors = ['#10b981', '#6ee7b7', '#e5e7eb', '#ff9a3d']
const frequencyBuckets = [{ key: '0', label: '0次（未训练）' }, { key: '1', label: '1次' }, { key: '2', label: '2次' }, { key: '3-4', label: '3–4次' }, { key: '5+', label: '5次及以上' }]
const deltaBuckets = [{ key: 'a', label: '≤−6' }, { key: 'b', label: '(−6,−3]' }, { key: 'c', label: '(−3,0)' }, { key: 'd', label: '[0,+3)' }, { key: 'e', label: '[+3,+6)' }, { key: 'f', label: '≥+6' }]
let generation = 0
async function load() { if(q.value.demo!=='1')return;const own = ++generation; loading.value = true; error.value = ''; try { const result = await loadTeacherWorkspace('demo', q.value); if (own === generation) data.value = result } catch (e) { if (own === generation) error.value = '教师数据加载失败，请检查服务状态后重试。' } finally { if (own === generation) loading.value = false } }
watch(() => [q.value.demo, q.value.insights, q.value.classId].join('|'), load, { immediate: true })
watch(() => route.fullPath, () => { drawer.value = null })
watch(() => JSON.stringify([route.path, Object.entries(q.value).filter(([key]) => !['page', 'item'].includes(key)).sort()]), () => { selected.value = [] })
const contexts = ['from', 'to', 'classIds', 'analyticsFrom', 'analyticsTo', 'class', 'classId', 'insights', 'returnClass', 'position', 'period', 'semester', 'demo']
function link(path, extra = {}) { const query=teacherContext(q.value); Object.assign(query, extra); if (/^\/teacher\/(reports|students|tasks)\//.test(path)) query.returnTo = route.fullPath; return { path, query } }
function set(key, value) { const query = { ...q.value, [key]: String(value || '') }; if (!value) delete query[key]; if(key==='class'){delete query.classId;delete query.classIds}  if (key !== 'page') delete query.page; if(key==='period'){for(const k of ['from','to','analyticsFrom','analyticsTo','timeRange'])delete query[k]} router.replace({ query }) }
function toggle(key, value) { set(key, q.value[key] === value ? '' : value) }
function switchMode() { router.replace({ query: { demo: q.value.demo === '1' ? undefined : '1' } }) }
function clearLocal() { router.replace({ query: link(route.path).query }) }
const filtered = computed(() => data.value ? filterData(data.value, q.value) : { students: [], records: [], tasks: [], pending: [], overdue: [], declining: [] })
const trainedCount = computed(() => filtered.value.students.filter(s => s.count > 0).length)
const participation = computed(() => percent(trainedCount.value).toFixed(0))
function percent(count) { return count / Math.max(1, filtered.value.students.length) * 100 }
watch(() => [q.value.class, q.value.position, q.value.period, q.value.semester], async () => { clearTimeout(refreshTimer); refreshing.value = false; await nextTick(); refreshing.value = true; refreshTimer = setTimeout(() => { refreshing.value = false }, 220) })
function focusPosition() { document.querySelector('.global-filters select[aria-label="岗位"]')?.focus() }
function resetOverviewFilters() { router.replace({ query: q.value.demo === '1' ? { demo: '1' } : {} }) }
const deadlineDays = t => Math.round((Date.parse(t.deadline.slice(0, 10) + 'T00:00:00Z') - Date.parse(data.value.referenceDate.slice(0, 10) + 'T00:00:00Z')) / 86400000)
const deadlineText = t => { const days = deadlineDays(t); return days < 0 ? '逾期' + Math.abs(days) + '天' : days === 0 ? '今日截止' : '剩余' + days + '天' }
const trend = computed(() => data.value ? dailyTrend(data.value, filtered.value.records, q.value) : [])
const comparableStudents = computed(() => filtered.value.students.filter(s => s.growth.delta !== null))
const abilityValues=computed(()=>!q.value.position?[]:abilities.map(name=>{
 const groups=new Map();for(const s of filtered.value.students){const snap=currentAbility(data.value.records,s,name,name==='专业知识'?'role':'common',q.value,data.value.now);if(snap.current!==null){const values=groups.get(snap.version)||[];values.push(snap.current);groups.set(snap.version,values)}}
 const [version,values]=[...groups].sort((a,b)=>b[1].length-a[1].length)[0]||[null,[]];return {name,version,value:values.length?Math.round(values.reduce((n,v)=>n+v,0)/values.length*10)/10:null}
}).filter(a=>a.value!==null))
const activeTasks=computed(()=>filtered.value.tasks.filter(t=>lifecycle(t,data.value.now)==='ACTIVE').sort((a,b)=>Date.parse(a.deadline)-Date.parse(b.deadline)).slice(0,5))
const taskTotal = t => t.completed + t.ongoing + t.notStarted + t.overdue
const metrics = computed(() => {
  const total = filtered.value.tasks.reduce((sum, t) => sum + taskTotal(t), 0), done = filtered.value.tasks.reduce((sum, t) => sum + t.completed, 0), improved = filtered.value.students.filter(s => s.growth.status === '有效提升').length
  return [{ title: '学生总数', value: filtered.value.students.length, unit: '人', note: `来自${new Set(filtered.value.students.map(s => s.className)).size}个教学班`, action: '学生管理', path: '/teacher/students' }, { title: '训练活跃度', value: `${trainedCount.value} / ${participation.value}%`, unit: '', note: '当前周期有有效训练记录', action: '查看活跃情况', path: '/teacher/activity' }, { title: '训练次数', value: filtered.value.records.length, unit: '次', note: '当前周期全部有效训练记录', action: '查看训练明细', path: '/teacher/training-records' }, { title: '任务完成率', value: total ? `${Math.round(done / total * 100)}%` : '—', unit: '', note: `${done} / ${total}人次 · 全部班级任务全周期`, action: '任务完成报告', path: '/teacher/tasks', query: { view: 'completion' } }, { title: '能力提升学生', value: improved, unit: '人', note: `${comparableStudents.value.length}名学生有充分对比数据`, action: '查看成长情况', path: '/teacher/growth' }, { title: '待点评报告', value: filtered.value.pending.length, unit: '份', note: `涉及${new Set(filtered.value.pending.map(r => r.studentId)).size}名学生`, action: '去点评', path: '/teacher/reviews', query: { tab: 'pending' } }]
})
const liveMetrics = computed(() => [{ title: '学生总数', value: data.value?.overview.summary?.studentTotal ?? '—', note: '当前接口全体学生统计', action: '学生管理', path: '/teacher/students' }, ...[{ title: '训练活跃度', path: '/teacher/activity' }, { title: '训练次数', path: '/teacher/training-records' }, { title: '任务完成率', path: '/teacher/tasks' }, { title: '能力提升学生', path: '/teacher/growth' }, { title: '待点评报告', path: '/teacher/reviews' }].map(m => ({ ...m, value: '—', note: '当前接口暂未提供此口径', action: '查看详情' }))])
const attention = computed(() => [...new Map([...filtered.value.declining,...filtered.value.students.filter(s=>!s.count||daysAgo(s.last)>7)].map(s=>[s.id,s])).values()].slice(0,3))
const todos = computed(() => [{ tab: 'pending', label: '待点评报告', count: filtered.value.pending.length, action: '去点评' }, { tab: 'overdue', label: '任务逾期', count: filtered.value.overdue.length, action: '查看学生' }, { tab: 'declining', label: '连续下降', count: filtered.value.declining.length, action: '查看详情' }])
const tab = computed(() => ['pending', 'overdue', 'declining'].includes(q.value.tab) ? q.value.tab : 'pending')
const student = id => filtered.value.students.find(s => s.id === id) || data.value?.students.find(s => s.id === id)
const task = id => data.value?.tasks.find(t => t.id === id)
const activityCount = status => filtered.value.students.filter(s => s.activity === status).length
const growthCount = status => filtered.value.students.filter(s => s.growth.status === status).length
function frequencyMatches(count, key) { return key === '5+' ? count >= 5 : key === '3-4' ? count >= 3 && count <= 4 : count === Number(key) }
const frequencyCount = key => filtered.value.students.filter(s => frequencyMatches(s.count, key)).length
function deltaKey(d) { return d <= -6 ? 'a' : d <= -3 ? 'b' : d < 0 ? 'c' : d < 3 ? 'd' : d < 6 ? 'e' : 'f' }
const deltaCount = key => comparableStudents.value.filter(s => deltaKey(s.growth.delta) === key).length
function filterFrequency(key) { if (key === '0') router.push(link('/teacher/activity', { activity: '未训练' })); else toggle('frequency', key) }
const studentRows = computed(() => {
  let rows = filtered.value.students.filter(s => (!q.value.search || `${s.name}${s.number}`.includes(q.value.search)) && (!q.value.activity || s.activity === q.value.activity) && (!q.value.growth || s.growth.status === q.value.growth) && (!q.value.delta || (s.growth.delta !== null && deltaKey(s.growth.delta) === q.value.delta)) && (!q.value.ability || s.growth.changes?.[0]?.name === q.value.ability))
  const last = q.value.last
  if (last) rows = rows.filter(s => last === 'never' ? !s.last : last === 'older' ? !!s.last && daysAgo(s.last) > 7 : !!s.last && daysAgo(s.last) <= (last === 'today' ? 0 : Number(last)))
  return rows.sort((a, b) => {
    const sort = q.value.sort
    if (sort === 'most') return b.count - a.count
    if (sort === 'least') return a.count - b.count
    if (sort === 'recent' || sort === 'oldest') return (daysAgo(a.last) - daysAgo(b.last) || 0) * (sort === 'oldest' ? -1 : 1)
    if (sort === 'deltaDesc' || sort === 'deltaAsc') { if (a.growth.delta === null) return 1; if (b.growth.delta === null) return -1; return (a.growth.delta - b.growth.delta) * (sort === 'deltaDesc' ? -1 : 1) }
    return surface.value === 'growth' ? ['持续下降', '轻微下降', '数据不足', '基本稳定', '有效提升'].indexOf(a.growth.status) - ['持续下降', '轻微下降', '数据不足', '基本稳定', '有效提升'].indexOf(b.growth.status) : a.count - b.count
  })
})
const recordRows = computed(() => {
  const comparable = new Set(filtered.value.students.flatMap(s => s.growth.records.map(r => r.id)))
  return filtered.value.records.filter(r => (!q.value.frequency || frequencyMatches(student(r.studentId).count, q.value.frequency)) && (!q.value.type || r.type === q.value.type) && (!q.value.source || r.source === q.value.source) && (!q.value.taskId || r.taskId === q.value.taskId) && (!q.value.content || r.content === q.value.content) && (!q.value.date || r.completedAt.slice(0, 10) === q.value.date) && (!q.value.comparable || comparable.has(r.id)) && (!q.value.search || `${student(r.studentId)?.name}${student(r.studentId)?.number}${r.content}`.includes(q.value.search))).sort((a, b) => (timestamp(b.completedAt) - timestamp(a.completedAt)) * (q.value.sort === 'oldest' ? -1 : 1))
})
const reviewRows = computed(() => {
  const rows = tab.value === 'pending' ? filtered.value.pending : tab.value === 'overdue' ? filtered.value.overdue : filtered.value.declining.map(s => ({ ...s, studentId: s.id }))
  const result = rows.filter(item => (!q.value.taskId || item.taskId === q.value.taskId) && (!q.value.search || `${student(item.studentId)?.name}${student(item.studentId)?.number}${item.content || task(item.taskId)?.name || ''}`.includes(q.value.search)))
  return q.value.sort === 'oldest' ? result.toReversed() : result
})
const rowCount = computed(() => surface.value === 'training-records' ? recordRows.value.length : surface.value === 'reviews' ? reviewRows.value.length : studentRows.value.length)
const totalPages = computed(() => Math.max(1, Math.ceil(rowCount.value / 10)))
const page = computed(() => Math.max(1, Math.min(totalPages.value, Number(q.value.page) || 1)))
const paged = rows => rows.slice((page.value - 1) * 10, page.value * 10)
const pagedStudents = computed(() => paged(studentRows.value)), pagedRecords = computed(() => paged(recordRows.value)), pagedReviews = computed(() => paged(reviewRows.value))
const currentReview = computed(() => pagedReviews.value.find(r => r.id === q.value.item) || pagedReviews.value[0])
const allSelected = computed(() => pagedStudents.value.length > 0 && pagedStudents.value.every(s => selected.value.includes(s.id)))
function selectPage(checked) { selected.value = checked ? [...new Set([...selected.value, ...pagedStudents.value.map(s => s.id)])] : selected.value.filter(id => !pagedStudents.value.some(s => s.id === id)) }
function pendingFinding(record){const scores=Object.entries(record.dimensions||record.common||{}).filter(([,v])=>Number.isFinite(v)&&v>=0&&v<=100).sort((a,b)=>a[1]-b[1]);const lowest=scores[0];return !lowest?'暂无有效通用能力评分':lowest[1]<80?lowest[0]+' '+lowest[1].toFixed(1)+'，低于演示目标80':'已有通用能力评分均达到演示目标80'}
const selectedOverdue = computed(() => filtered.value.overdue.filter(o => selected.value.includes(o.id)))
const canExtend = computed(() => selectedOverdue.value.length > 0 && new Set(selectedOverdue.value.map(o => o.taskId)).size === 1)
const extendReason = computed(() => !selected.value.length ? '请先选择同一任务的学生' : canExtend.value ? '' : '跨任务选择不能批量延期')
function extend() {
 if(!canExtend.value||!newDeadline.value){actionError.value='请选择同一任务并填写新截止日期。';return}
 try { const target=loadTasks().find(t=>t.id===selectedOverdue.value[0].taskId);extendDeadline(target,newDeadline.value+'T23:59','教师待办中心延期',data.value.now);actionSuccess.value='任务延期已保存，新截止日期为'+newDeadline.value+'，适用于该任务全部参与学生。';data.value=getDemoWorkspace(q.value);selected.value=[];drawer.value=null;actionError.value='' } catch(e){actionError.value=e.message}
}
function showStudent(id) { const item = student(id); if (item) drawer.value = { type: 'student', item } }
function showDate(dateValue) { const item = trend.value.find(p => p.date === dateValue); if (item) drawer.value = { type: 'date', item } }
const drawerTitle = computed(() => ({ rules: '成长判定规则', growth: '学生成长详情', record: '专项训练记录', student: '学生快速信息', date: '当天训练详情', extend: '批量延长截止时间' })[drawer.value?.type])
function date(value) { return value ? new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }) : '—' }
const decimal = value => Number.isFinite(value) ? value.toFixed(1) : '—'
const signed = value => Number.isFinite(value) ? `${value > 0 ? '+' : ''}${value.toFixed(1)}` : '—'
const tone = status => ['低活跃', '轻微下降', '待点评'].includes(status) ? 'warn' : status === '持续下降' ? 'danger' : ['未训练', '数据不足'].includes(status) ? 'neutral' : ''
</script>

